import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"kiwa v1.46 リリース — quality gate integrity 回復 + DevSecOps library 化 (2 軸 milestone、 40 package 到達)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.46/zenn-article.md","filePath":"announcements/v1.46/zenn-article.md"}'),r={name:"announcements/v1.46/zenn-article.md"};function l(n,e,o,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="kiwa-v1-46-リリース-—-quality-gate-integrity-回復-devsecops-library-化-2-軸-milestone、-40-package-到達" tabindex="-1">kiwa v1.46 リリース — quality gate integrity 回復 + DevSecOps library 化 (2 軸 milestone、 40 package 到達) <a class="header-anchor" href="#kiwa-v1-46-リリース-—-quality-gate-integrity-回復-devsecops-library-化-2-軸-milestone、-40-package-到達" aria-label="Permalink to &quot;kiwa v1.46 リリース — quality gate integrity 回復 + DevSecOps library 化 (2 軸 milestone、 40 package 到達)&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>kiwa v1.46 をリリースしました。 <strong>quality gate integrity 回復 + DevSecOps library 化 の 2 軸 milestone</strong>。 v1.25 で docs 記載した「33 package sweep」 と実態 15 package の gap + v1.42-v1.45 で追加された advanced III axis の baseline 未生成 gap を解消、 dev-flow の /security-audit skill 4 種を library 経由で test 可能な形に置換する Phase 1 完成。</p><h2 id="何が変わったか" tabindex="-1">何が変わったか <a class="header-anchor" href="#何が変わったか" aria-label="Permalink to &quot;何が変わったか&quot;">​</a></h2><h3 id="kiwa-lab-perf-harness-v0-3-0-strict-mode" tabindex="-1"><code>@kiwa-lab/perf-harness</code> v0.3.0 strict mode <a class="header-anchor" href="#kiwa-lab-perf-harness-v0-3-0-strict-mode" aria-label="Permalink to &quot;`@kiwa-lab/perf-harness` v0.3.0 strict mode&quot;">​</a></h3><ul><li><code>detectRegressionStrict</code> (|t|&gt;3 + delta 10%) 追加</li><li><code>runPerf3LayerStrict</code> (iter 400 + concurrency 20 + memory 400) 追加</li><li>v0.2 lax mode (|t|&gt;2 + 20% + iter 200) は backward compat として維持</li><li>test 漏れゼロを狙う fail-fast mode</li></ul><h3 id="kiwa-lab-quality-metrics-v0-4-0-15-axis" tabindex="-1"><code>@kiwa-lab/quality-metrics</code> v0.4.0 15 axis <a class="header-anchor" href="#kiwa-lab-quality-metrics-v0-4-0-15-axis" aria-label="Permalink to &quot;`@kiwa-lab/quality-metrics` v0.4.0 15 axis&quot;">​</a></h3><ul><li><code>PerfMetric</code> に <code>strict</code> + <code>baselineExists</code> field 追加</li><li><code>ReleaseGateThresholds</code> に <code>perfStrictP95Ms</code> (default 50) + <code>perfStrictRequireBaseline</code> (default true) 追加</li><li><code>evaluateReleaseGate</code> に <code>perf.strict.p95Ms</code> + <code>perf.strict.baseline</code> axis 追加 (<code>strict = true</code> 時のみ発火)</li><li>13 → 15 axis 拡張、 backward compat</li></ul><h3 id="kiwa-lab-security-devsecops-v0-1-0-新規-40-package-到達" tabindex="-1"><code>@kiwa-lab/security-devsecops</code> v0.1.0 新規 (40 package 到達) <a class="header-anchor" href="#kiwa-lab-security-devsecops-v0-1-0-新規-40-package-到達" aria-label="Permalink to &quot;`@kiwa-lab/security-devsecops` v0.1.0 新規 (40 package 到達)&quot;">​</a></h3><p>6 axis の state machine + neutral event pattern。</p><ul><li><strong>SAST</strong> (Semgrep-style) — startSastScan + detectSastFinding + suppressSastFinding + completeSastScan</li><li><strong>SCA</strong> (Trivy-style) — startScaScan + analyzeScaDependency + detectScaVuln + flagScaLicense + completeScaScan</li><li><strong>Secret scan</strong> (Gitleaks-style) — startSecretScan + matchSecretPattern + flagSecretEntropy + allowlistSecret + completeSecretScan</li><li><strong>IaC scan</strong> (tfsec-style) — startIacScan + analyzeIacResource + detectIacMisconfig + checkIacCompliance + completeIacScan</li><li><strong>DAST</strong> (OWASP ZAP-style) — startDastScan + crawlDastUrls + attemptDastAttack + confirmDastVuln + completeDastScan</li><li><strong>Container security</strong> (Grype-style) — startContainerScan + scanContainerImage + detectContainerCve + flagContainerMalware + completeContainerScan</li></ul><h3 id="_38-package-perf-baseline-完全-sweep" tabindex="-1">38 package perf baseline 完全 sweep <a class="header-anchor" href="#_38-package-perf-baseline-完全-sweep" aria-label="Permalink to &quot;38 package perf baseline 完全 sweep&quot;">​</a></h3><ul><li>security package の perf test + baseline 追加 (残 gap 解消)</li><li>4 stale baseline refresh (realtime v0.3 / observability v2.2 / ai-llm v0.5 / auth v0.6)</li><li>38 package quality gate SSOT integrity 完全回復</li></ul><h3 id="_1-new-dogfood-app-2-tutorial" tabindex="-1">1 new dogfood app + 2 tutorial <a class="header-anchor" href="#_1-new-dogfood-app-2-tutorial" aria-label="Permalink to &quot;1 new dogfood app + 2 tutorial&quot;">​</a></h3><ul><li><code>dogfood-security-devsecops-app</code> — 6 axis chain 実行 (8 test)</li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/103-security-devsecops" target="_blank" rel="noreferrer">Tutorial 103 — DevSecOps 6 axis</a></strong></li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/104-perf-strict" target="_blank" rel="noreferrer">Tutorial 104 — Perf strict mode</a></strong></li></ul><h2 id="_24-milestone-連続-snippet-validation-streak-達成" tabindex="-1">24 milestone 連続 snippet validation streak 達成 <a class="header-anchor" href="#_24-milestone-連続-snippet-validation-streak-達成" aria-label="Permalink to &quot;24 milestone 連続 snippet validation streak 達成&quot;">​</a></h2><p>v1.23 → v1.46 で 24 milestone 連続。 kiwa 史上最長記録更新継続。</p><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/perf-harness@^0.3</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/quality-metrics@^0.4</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/security-devsecops@^0.1</span></span></code></pre></div><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v1.45-to-v1.46" target="_blank" rel="noreferrer">v1.45 → v1.46</a></p><h2 id="次に何が来るか" tabindex="-1">次に何が来るか <a class="header-anchor" href="#次に何が来るか" aria-label="Permalink to &quot;次に何が来るか&quot;">​</a></h2><p>v1.47 = security-devsecops v0.2 adapter 統合 (実 semgrep / trivy CLI 隠蔽) or 他 pair-2 3 段化 (Streaming / Database / Frontend / Security)。 v1.48 前後 = new base pair 第 13 導入 (5-milestone cadence)。</p>',23)])])}const g=a(r,[["render",l]]);export{k as __pageData,g as default};
